CREATE TABLE users (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('agent','admin')), password_hash TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), device TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE contacts (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', owner_id TEXT NOT NULL REFERENCES users(id), first TEXT, last TEXT, mobile TEXT, email TEXT, roles TEXT, tags TEXT, flags TEXT, consent TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE contact_notes (id TEXT PRIMARY KEY, contact_id TEXT NOT NULL REFERENCES contacts(id), user_id TEXT REFERENCES users(id), d TEXT, a TEXT, t TEXT, created_at TEXT NOT NULL);
CREATE TABLE properties (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', no TEXT, street TEXT, suburb TEXT, geometry TEXT, pf_owner TEXT, last_sale TEXT, flags TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE property_owners (property_id TEXT NOT NULL REFERENCES properties(id), contact_id TEXT NOT NULL REFERENCES contacts(id), relation TEXT NOT NULL DEFAULT 'owner', PRIMARY KEY(property_id,contact_id));
CREATE TABLE todos (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', due TEXT, time TEXT, text TEXT, assignee_id TEXT NOT NULL REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), kind TEXT, done INTEGER DEFAULT 0, contact_id TEXT, property_id TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE INDEX contacts_scope ON contacts(owner_id,updated_at);
CREATE INDEX todos_scope ON todos(assignee_id,created_by,updated_at);
CREATE INDEX properties_updated ON properties(updated_at);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, device TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, diff TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE rex_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, entity TEXT NOT NULL, entity_id TEXT NOT NULL, op TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'waiting_auth', tries INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL);
CREATE TABLE captures (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', text TEXT, audio_ref TEXT, status TEXT, property_id TEXT, extracted TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE enquiries (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', source TEXT, status TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE leads (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', contact_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE listings (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', property_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE ofi_events (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', listing_id TEXT, at TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE ofi_attendees (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', event_id TEXT, contact_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE sales (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', property_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE contracts (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', listing_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE referrals (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', contact_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE market_items (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', property_id TEXT, payload TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE zones (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', name TEXT, geometry TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE tags (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', name TEXT, owner_id TEXT, sort INTEGER DEFAULT 0, usage_count INTEGER DEFAULT 0, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
CREATE TABLE approvals (id TEXT PRIMARY KEY, team_id TEXT NOT NULL DEFAULT 'default', kind TEXT, payload TEXT, status TEXT, requested_by TEXT, decided_by TEXT, created_at TEXT, updated_at TEXT, version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT);
